DROP INDEX "notification_events_unseen_ticket_idx";--> statement-breakpoint
CREATE INDEX "notification_events_unseen_ticket_idx" ON "notification_events" USING btree ("user_id",("payload" ->> 'ticketId'),"created_at") WHERE ("notification_events"."kind" in ('ticket.created', 'ticket.unassigned', 'ticket.message', 'ticket.status', 'ticket.updated', 'ticket.tasks', 'ticket.assigned', 'ticket.time_missing', 'ticket.awaiting_confirmation', 'ticket.confirmation_declined', 'ticket.time_review', 'ticket.resolved', 'chat.mention', 'description.mention') and ("notification_events"."payload" ->> 'ticketId') is not null);